def record(acct, cents, note):
    if cents >= 0:
        sign = "+"
        digits = str(cents)
    else:
        sign = "-"
        digits = str(-cents)
    s = sum(int(d) for d in digits)
    check = s % 10
    amount = f"{sign}{digits}#{check}"
    try:
        result = ledger.post(acct, amount, memo=note)
    except ledger.PostError:
        raise
    return result

